begin;
create function pg_temp.assert(ok boolean,label text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'FAIL: %',label; end if; raise notice 'PASS: %',label; end $$;
create function pg_temp.reject(command text,expected text,label text) returns void language plpgsql as $$ begin
 begin execute command; raise exception 'accepted unexpectedly'; exception when others then if sqlerrm<>expected then raise; end if;end;
 perform pg_temp.assert(true,label);
end $$;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select public.save_coaching_form('a2000000-0000-4000-8000-000000000001','Reflection','checkin','[{"id":"energy","label":"Energy","type":"number","required":true,"min":1,"max":5,"unit":"score"},{"id":"note","label":"Notes","type":"text","required":false},{"id":"ready","label":"Ready","type":"boolean","required":true}]',0);
select pg_temp.assert((public.save_coaching_form('a2000000-0000-4000-8000-000000000001','Reflection','checkin','[{"id":"energy","label":"Energy","type":"number","required":true,"min":1,"max":5,"unit":"score"},{"id":"note","label":"Notes","type":"text","required":false},{"id":"ready","label":"Ready","type":"boolean","required":true}]',0)).revision=1,'form retry preserves version');
select pg_temp.reject($q$select public.save_coaching_form('a2000000-0000-4000-8000-000000000001','Changed','checkin','[]',1)$q$,'invalid_fields','empty definitions rejected');
select pg_temp.reject($q$select public.assign_coaching_form(gen_random_uuid(),'40000000-0000-4000-8000-000000000001','a2000000-0000-4000-8000-000000000001',1,current_date,13,7)$q$,'invalid_schedule','recurrence is bounded to twelve occurrences');
select count(*) from public.assign_coaching_form('a3000000-0000-4000-8000-000000000001','40000000-0000-4000-8000-000000000001','a2000000-0000-4000-8000-000000000001',1,current_date,3,7);
select count(*) from public.assign_coaching_form('a3000000-0000-4000-8000-000000000001','40000000-0000-4000-8000-000000000001','a2000000-0000-4000-8000-000000000001',1,current_date,3,7);
select pg_temp.assert((select count(*)=3 and max(due_date)-min(due_date)=14 from public.coaching_requests where series_id='a3000000-0000-4000-8000-000000000001'),'assign retry produces one bounded series');
select pg_temp.reject($q$select public.assign_coaching_form('a3000000-0000-4000-8000-000000000001','40000000-0000-4000-8000-000000000001','a2000000-0000-4000-8000-000000000001',1,current_date,3,14)$q$,'conflict','series ID cannot be reused with different recurrence');
select public.save_coaching_form('a2000000-0000-4000-8000-000000000001','New questions','assessment','[{"id":"hold","label":"Hold","type":"number","unit":"s","min":0,"required":true}]',1);
select pg_temp.assert((select bool_and(title='Reflection' and fields->0->>'unit'='score' and form_revision=1) from public.coaching_requests where series_id='a3000000-0000-4000-8000-000000000001'),'assigned questions and units are immutable after template edits');
select set_config('r2.request',(select id::text from public.coaching_requests where series_id='a3000000-0000-4000-8000-000000000001' order by due_date limit 1),true);
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select pg_temp.assert(not exists(select 1 from public.coaching_forms where id='a2000000-0000-4000-8000-000000000001'),'client receives assignment snapshots without private template access');
select public.save_coaching_response(current_setting('r2.request')::uuid,'{"note":"Draft"}',1,false);
select pg_temp.assert((select submitted_at is null and revision=2 from public.coaching_requests where id=current_setting('r2.request')::uuid),'incomplete draft persists without submission');
select pg_temp.reject($q$select public.save_coaching_response(current_setting('r2.request')::uuid,'{"note":"Draft"}',2,true)$q$,'required_answer','required questions gate submission');
select pg_temp.reject($q$select public.save_coaching_response(current_setting('r2.request')::uuid,'{"energy":6,"ready":true}',2,true)$q$,'invalid_answers','numeric bounds validated transactionally');
select pg_temp.reject($q$select public.save_coaching_response(current_setting('r2.request')::uuid,'{"energy":4,"ready":"yes"}',2,true)$q$,'invalid_answers','boolean fields reject arbitrary text');
select pg_temp.reject($q$select public.save_coaching_response(current_setting('r2.request')::uuid,'{"energy":4,"ready":true,"unknown":7}',2,true)$q$,'invalid_answers','unknown answers cannot bypass the assigned definition');
select public.save_coaching_response(current_setting('r2.request')::uuid,'{"energy":4,"ready":false}',2,true);
select pg_temp.assert((public.save_coaching_response(current_setting('r2.request')::uuid,'{"energy":4,"ready":false}',2,true)).revision=3,'submitted response retry preserves revision');
select set_config('r2.submitted',(select submitted_at::text from public.coaching_requests where id=current_setting('r2.request')::uuid),true);
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select pg_temp.reject($q$select public.save_coaching_response(current_setting('r2.request')::uuid,'{"energy":1}',3,true)$q$,'forbidden','coach cannot answer as client');
select public.review_coaching_response(current_setting('r2.request')::uuid,3,'We will adjust the week.');
select pg_temp.assert((public.review_coaching_response(current_setting('r2.request')::uuid,3,'We will adjust the week.')).revision=4,'review retries do not create another revision');
select pg_temp.reject($q$select public.cancel_coaching_request(current_setting('r2.request')::uuid,4)$q$,'already_submitted','completed response cannot be cancelled');
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select pg_temp.reject($q$select public.save_coaching_response(current_setting('r2.request')::uuid,'{"energy":3,"ready":true}',3,true)$q$,'conflict','stale response cannot overwrite coach review');
select public.save_coaching_response(current_setting('r2.request')::uuid,'{"energy":3,"ready":true}',4,true);
select pg_temp.assert((select submitted_at=current_setting('r2.submitted')::timestamptz and reviewed_at is null and feedback='' and revision=5 from public.coaching_requests where id=current_setting('r2.request')::uuid),'correction preserves original submission and clears obsolete review');
select public.save_measurement('a4000000-0000-4000-8000-000000000001',null,'weight',current_date,165,'lb',0);
select public.save_measurement('a4000000-0000-4000-8000-000000000002','40000000-0000-4000-8000-000000000001','waist',current_date,82,'cm',0);
select pg_temp.assert((public.save_measurement('a4000000-0000-4000-8000-000000000002','40000000-0000-4000-8000-000000000001','waist',current_date,82,'cm',0)).revision=1,'measurement retry creates no duplicate');
select pg_temp.reject($q$select public.save_measurement(gen_random_uuid(),null,'weight',current_date,70,'cm',0)$q$,'invalid_measurement','measurement metric and unit must agree');
select pg_temp.reject($q$select public.save_measurement('a4000000-0000-4000-8000-000000000002','40000000-0000-4000-8000-000000000001','waist',current_date,83,'cm',0)$q$,'conflict','stale measurement correction rejected');
select public.send_message('a5000000-0000-4000-8000-000000000001','40000000-0000-4000-8000-000000000001','About this response',null,current_setting('r2.request')::uuid);
select public.send_message('a5000000-0000-4000-8000-000000000001','40000000-0000-4000-8000-000000000001','About this response',null,current_setting('r2.request')::uuid);
select pg_temp.assert((select count(*)=1 from public.messages where id='a5000000-0000-4000-8000-000000000001'),'send retry yields exactly one persistent message');
select pg_temp.reject($q$select public.send_message('a5000000-0000-4000-8000-000000000001','40000000-0000-4000-8000-000000000001','Changed payload')$q$,'conflict','stable message ID rejects a different payload');
select pg_temp.reject($q$select public.send_message(gen_random_uuid(),'40000000-0000-4000-8000-000000000001','Bad context','a9999999-0000-4000-8000-000000000001')$q$,'invalid_context','message cannot link an unrelated workout');
do $$ declare s jsonb; entries jsonb; results jsonb; before_time text; sid uuid:=gen_random_uuid(); begin
 s:=public.start_session(sid,'30000000-0000-4000-8000-000000000001','foundation-a');
 entries:=jsonb_set(jsonb_set(s->'entries','{0,load}','33'),'{0,completed}','true');
 s:=public.save_session(sid,1,gen_random_uuid(),entries,'Progress assertion',true);before_time:=s->>'completed_at';
 select x into results from jsonb_array_elements(public.training_progress(null,(s->>'local_date')::date,(s->>'local_date')::date)) x where x->>'id'=sid::text;
 perform pg_temp.assert(exists(select 1 from jsonb_array_elements(results->'exercises') e where (e#>>'{sets,0,load}')::numeric=33) and (select sum(jsonb_array_length(e->'sets')) from jsonb_array_elements(results->'exercises') e)=1,'progress uses completed actual sets rather than targets or incomplete sets');
 entries:=jsonb_set(entries,'{0,load}','34');
 s:=public.save_session(sid,(s->>'version')::int,gen_random_uuid(),entries,'Progress corrected',true);
 select x into results from jsonb_array_elements(public.training_progress(null,(s->>'local_date')::date,(s->>'local_date')::date)) x where x->>'id'=sid::text;
 perform pg_temp.assert(exists(select 1 from jsonb_array_elements(results->'exercises') e where (e#>>'{sets,0,load}')::numeric=34) and s->>'completed_at'=before_time,'progress recomputes corrections without creating another completion');
end $$;
select pg_temp.assert(jsonb_array_length(public.training_progress(null,current_date-365,current_date))>=2,'client progress uses completed acknowledged sessions');
select pg_temp.reject($q$select public.training_progress(null,current_date-366,current_date)$q$,'invalid_window','progress queries are bounded');
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select pg_temp.assert(not exists(select 1 from public.measurements where id='a4000000-0000-4000-8000-000000000001') and exists(select 1 from public.measurements where id='a4000000-0000-4000-8000-000000000002'),'coach sees explicitly shared measurements only');
select pg_temp.reject($q$select public.review_coaching_response(current_setting('r2.request')::uuid,4,'Stale')$q$,'conflict','review must reference the corrected response revision');
select pg_temp.assert(exists(select 1 from jsonb_array_elements(public.conversation_inbox()) x where x->>'id'='40000000-0000-4000-8000-000000000001' and (x->>'unread')::int>=1),'inbox derives unread from persisted incoming messages');
select public.mark_conversation_read('40000000-0000-4000-8000-000000000001',(select sequence from public.messages where id='a5000000-0000-4000-8000-000000000001'));
select pg_temp.assert(exists(select 1 from jsonb_array_elements(public.conversation_inbox()) x where x->>'id'='40000000-0000-4000-8000-000000000001' and x->>'unread'='0'),'read cursor clears observed incoming messages');
select pg_temp.reject($q$select public.mark_conversation_read('40000000-0000-4000-8000-000000000001',9223372036854775807)$q$,'invalid_cursor','cursor cannot mark future messages as read');
select public.send_message('a5000000-0000-4000-8000-000000000002','40000000-0000-4000-8000-000000000001','Reply');
select public.mark_conversation_read('40000000-0000-4000-8000-000000000001',(select sequence from public.messages where id='a5000000-0000-4000-8000-000000000002'));
select public.mark_conversation_read('40000000-0000-4000-8000-000000000001',(select sequence from public.messages where id='a5000000-0000-4000-8000-000000000001'));
select pg_temp.assert((select last_sequence=(select sequence from public.messages where id='a5000000-0000-4000-8000-000000000002') from public.conversation_reads where relationship_id='40000000-0000-4000-8000-000000000001'),'read cursor never moves backwards');
select public.set_client_state('40000000-0000-4000-8000-000000000001','archived');
select pg_temp.reject($q$select public.send_message(gen_random_uuid(),'40000000-0000-4000-8000-000000000001','New')$q$,'relationship_archived','archived conversation blocks new sends');
select pg_temp.assert((select count(*) from public.messages where id='a5000000-0000-4000-8000-000000000001')=1,'archive retains conversation history');
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select pg_temp.reject($q$select public.save_coaching_response(current_setting('r2.request')::uuid,'{"energy":2,"ready":false}',5,true)$q$,'request_unavailable','archived relationship blocks new responses');
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000004","role":"authenticated"}',true);
select pg_temp.assert(not exists(select 1 from public.coaching_requests where id=current_setting('r2.request')::uuid) and not exists(select 1 from public.messages where id='a5000000-0000-4000-8000-000000000001') and not exists(select 1 from public.measurements where id='a4000000-0000-4000-8000-000000000002'),'unrelated coach cannot read coaching records');
select pg_temp.reject($q$select public.training_progress('40000000-0000-4000-8000-000000000001',current_date-30,current_date)$q$,'forbidden','unrelated coach cannot query private progress');
select pg_temp.reject($q$select public.review_coaching_response(current_setting('r2.request')::uuid,5,'Foreign')$q$,'forbidden','unrelated coach cannot review a response');
select set_config('request.jwt.claims','{"sub":"10000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select pg_temp.reject($q$select public.send_message(gen_random_uuid(),'40000000-0000-4000-8000-000000000001','Foreign')$q$,'forbidden','unrelated client cannot send into another conversation');
select pg_temp.reject($q$select public.remove_measurement('a4000000-0000-4000-8000-000000000002',1)$q$,'forbidden','unrelated client cannot remove a measurement');
rollback;
